// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title Data Types Demonstration Contract
/// @notice This contract showcases various data types and storage patterns in Solidity
/// @dev Examples of different visibility modifiers, complex data structures, and storage patterns
contract DataTypesDemo {
    /// @notice Public string variable demonstrating string storage
    string public text;

    /// @notice Private number demonstrating private state variables
    uint256 private number;

    /// @notice Internal boolean flag demonstrating internal visibility
    bool internal flag;

    /// @notice Immutable owner address demonstrating immutable variables
    /// @dev Once set in constructor, this cannot be modified
    address public immutable owner;

    /// @notice Struct definition for storing person data
    /// @dev Demonstrates how to create custom data structures
    struct Person {
        string name;    // Person's name
        uint256 age;    // Person's age
        bool active;    // Person's active status
    }

    /// @notice Mapping of addresses to Person structs
    /// @dev Demonstrates key-value storage pattern
    mapping(address => Person) public people;

    /// @notice Array of member addresses
    /// @dev Demonstrates dynamic array usage
    address[] public membersList;

    /// @notice Event emitted when a new person is added
    /// @param userAddress The address of the added person
    /// @param name The name of the added person
    event PersonAdded(address indexed userAddress, string name);

    /// @notice Initializes the contract with a starting text
    /// @param initialText The initial text to store
    constructor(string memory initialText) {
        text = initialText;
        owner = msg.sender;
    }

    /// @notice Adds a new person to the contract
    /// @param _name The name of the person
    /// @param _age The age of the person
    /// @dev Demonstrates struct creation and storage
    function addPerson(string memory _name, uint256 _age) public {
        people[msg.sender] = Person(_name, _age, true);
        membersList.push(msg.sender);
        emit PersonAdded(msg.sender, _name);
    }

    /// @notice Updates the private number value
    /// @param _number The new number to store
    function updateNumber(uint256 _number) public {
        number = _number;
    }

    /// @notice Retrieves the private number value
    /// @return The current stored number
    function getNumber() public view returns (uint256) {
        return number;
    }

    /// @notice Toggles the internal flag
    /// @dev Demonstrates boolean operations
    function toggleFlag() public {
        flag = !flag;
    }

    /// @notice Gets the current state of the flag
    /// @return The current state of the flag
    function getFlag() public view returns (bool) {
        return flag;
    }
}

contracts/Lock.sol.content:
// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.28;

/// @title Time-locked Wallet Contract
/// @notice This contract demonstrates a simple time-locked wallet where funds can only be withdrawn after a specified time
/// @dev Uses block.timestamp for time calculations and basic access control
contract Lock {
    /// @notice The timestamp after which the funds can be withdrawn
    /// @dev Stored as Unix timestamp
    uint public unlockTime;

    /// @notice The address that can withdraw the funds
    /// @dev Set during contract deployment
    address payable public owner;

    /// @notice Emitted when funds are withdrawn from the contract
    /// @param amount The amount of ETH that was withdrawn
    /// @param when The timestamp when the withdrawal occurred
    event Withdrawal(uint amount, uint when);

    /// @notice Creates a new time-locked wallet
    /// @dev The constructor is payable to allow funding during deployment
    /// @param _unlockTime The Unix timestamp after which funds can be withdrawn
    constructor(uint _unlockTime) payable {
        require(
            block.timestamp < _unlockTime,
            "Unlock time should be in the future"
        );

        unlockTime = _unlockTime;
        owner = payable(msg.sender);
    }

    /// @notice Allows the owner to withdraw all funds after the unlock time
    /// @dev Transfers the entire contract balance to the owner
    /// @dev Emits a Withdrawal event upon successful transfer
    function withdraw() public {
        // Uncomment this line, and the import of "hardhat/console.sol", to print a log in your terminal
        // console.log("Unlock time is %o and block timestamp is %o", unlockTime, block.timestamp);

        require(block.timestamp >= unlockTime, "You can't withdraw yet");
        require(msg.sender == owner, "You aren't the owner");

        emit Withdrawal(address(this).balance, block.timestamp);

        owner.transfer(address(this).balance);
    }
}

contracts/ModifiersAndInheritance.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

/// @title Ownable Base Contract
/// @notice Implements basic access control mechanism with single owner
/// @dev Base contract demonstrating inheritance and modifiers
contract Ownable {
    /// @notice Address of the contract owner
    address public owner;

    /// @notice Emitted when contract ownership is transferred
    /// @param previousOwner Address of the previous owner
    /// @param newOwner Address of the new owner
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    /// @notice Sets the original owner of the contract to the sender
    constructor() {
        owner = msg.sender;
    }

    /// @notice Modifier to restrict function access to contract owner
    /// @dev Throws if called by any account other than the owner
    modifier onlyOwner() {
        require(msg.sender == owner, "Not the owner");
        _;
    }

    /// @notice Transfers ownership of the contract to a new address
    /// @param newOwner Address to receive ownership
    /// @dev Can only be called by current owner
    function transferOwnership(address newOwner) public onlyOwner {
        require(newOwner != address(0), "New owner cannot be zero address");
        emit OwnershipTransferred(owner, newOwner);
        owner = newOwner;
    }
}

/// @title Access Control Contract
/// @notice Extends Ownable to implement operator-level access control
/// @dev Demonstrates contract inheritance and additional access control patterns
contract AccessControl is Ownable {
    /// @notice Mapping of addresses to operator status
    mapping(address => bool) public operators;

    /// @notice Emitted when an operator is added
    /// @param operator Address that was granted operator status
    event OperatorAdded(address indexed operator);

    /// @notice Emitted when an operator is removed
    /// @param operator Address that was removed from operators
    event OperatorRemoved(address indexed operator);

    /// @notice Modifier to restrict access to operators or owner
    /// @dev Throws if called by non-operator and non-owner
    modifier onlyOperator() {
        require(operators[msg.sender] || msg.sender == owner, "Not authorized");
        _;
    }

    /// @notice Adds a new operator
    /// @param operator Address to be added as operator
    /// @dev Can only be called by contract owner
    function addOperator(address operator) public onlyOwner {
        operators[operator] = true;
        emit OperatorAdded(operator);
    }

    /// @notice Removes an operator
    /// @param operator Address to be removed from operators
    /// @dev Can only be called by contract owner
    function removeOperator(address operator) public onlyOwner {
        operators[operator] = false;
        emit OperatorRemoved(operator);
    }
}

contracts/USDTO.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title USDTO
 * @dev Test token pegged to USD on Conflux eSpace
 *      1 USDTO = 1 USD
 */
contract USDTO is ERC20, ERC20Burnable, Ownable {
    mapping(address => bool) public minters;

    event MinterAdded(address indexed minter);
    event MinterRemoved(address indexed minter);

    modifier onlyMinter() {
        require(minters[msg.sender] || msg.sender == owner(), "USDTO: not a minter");
        _;
    }

    constructor(address initialOwner) ERC20("AxPesa USD", "USDTO") Ownable(initialOwner) {
        _transferOwnership(initialOwner);
    }

    function mint(address to, uint256 amount) external onlyMinter {
        _mint(to, amount);
    }

    function addMinter(address minter) external onlyOwner {
        minters[minter] = true;
        emit MinterAdded(minter);
    }

    function removeMinter(address minter) external onlyOwner {
        minters[minter] = false;
        emit MinterRemoved(minter);
    }

    function isMinter(address account) external view returns (bool) {
        return minters[account];
    }
}

